// Algorithm for packing 24-bit colors into a single byte.
// Packing into 8-bits results in color loss.
// Recovering the color results in dark hues due to loss.
// Using bit "echos", we can improve the recovered colors.
//
// Bit Echo color unpacking algorithm developed by
// https://github.com/TheMaverickProgrammer

// Function from Iñigo Quiles
// https://www.shadertoy.com/view/MsS3Wc
vec3 hsb2rgb(vec3 c) {
    vec3 rgb = clamp(abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0,0.0,1.0);
    rgb = rgb*rgb*(3.0-2.0*rgb);
    return c.z * mix(vec3(1.0), rgb, c.y);
}

// Pack 3 high red, 3 mid green, last 2 blue
int pack(vec3 c) {
    return (int(c.r) & 0xE0) | ((int(c.g) >> 3) & 0x1C) | ((int(c.b) >> 6) & 0x03);
}

// Unpacks the way they were written in reverse
vec3 unpackBasic(int byte) {
    int r =  byte & 0xE0;
    int g = (byte & 0x1C) << 3;
    int b = (byte & 0x03) << 6;

    return vec3(float(r), float(g), float(b));
}

// Use the fact loss will happen with higher color values
// and repeat those bits in other positions like an echo
vec3 unpackWithEcho(int byte) {
    int r  = byte & 0xE0;
    int g  = byte & 0x1C;
    int b  = byte & 0x03;

    vec3 c = vec3(
        float(r        | (r >> 3)),
        float((g << 3) |       g) ,
        float((b << 6) | (b << 3))
    );

    return c;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalized pixel coordinates (from 0 to 1)
    vec2 st = fragCoord/iResolution.xy;

    // Calculate RGB for demonstration
    vec3 rgb = hsb2rgb(vec3(st.x,1.0,st.y));

    // Use 8-bit packing algorithm (lossy)
    int bits = pack(rgb*255.0);

    // Unpack with Echo method
    // Results: visually improved
    rgb = unpackWithEcho(bits)/255.0;

    // Comment out to see the comparison without animation.
    // Results: Before, the colors were too dark.
    //          With the algorithm, they're brighter.
    float moment = sin(st.x+iTime);
    if(moment <= 0.0) {
        rgb = unpackBasic(bits)/255.0;

        // Draw the line separating the two
        if(moment > -0.001 && moment < 0.001) {
            rgb = vec3(0.0);
        }
    }

    // Output to screen
    fragColor = vec4(rgb,1.0);
}
